a.injected_css:
.top, .steps, .log, .nav-buttons { display: none !important; }
.app { grid-template-rows: auto; height: auto; background: #fff; }
.form, .diagnostics { overflow: visible; }
.form { padding: 13px 16px 11px; }
.form h2, .diagnostics h2 { font-size: 26px; line-height: 1.15; margin-bottom: 6px; }
.form h3 { font-size: 22px; margin: 6px 0 3px; }
.viewer-label { font-size: 21px; }
.app { grid-template-columns: minmax(0, 1.55fr) minmax(0, 1fr); grid-template-areas: 'centre diag'; }
.centre { grid-template-rows: auto minmax(275px, 1fr); }
.form .row:not(:has(select option[value="drop"])):not(:has(select option[value="removed_zones"])),
.form > div > .inline, .form .hint, .form h3 { display: none; }
.form .row { grid-template-columns: 167px minmax(0, 1fr); gap: 6px; padding: 3px 0; }
.form .row > label, .form .row select { font-size: 21px; }
.form .row select { width: 100%; padding: 3px 5px; font: 400 21px/1.18 'Arial Narrow', Arial, sans-serif; }
.diagnostics { padding: 13px 12px 10px; }
.diagnostics ul { gap: 5px; }
.diagnostics li { padding: 6px 8px; }
.diagnostics li:first-child { display: none; }
.diagnostics .title, .diagnostics .detail { font-size: 21px; line-height: 1.12; }

a.embedded_viewer_css:
.shell { background: #fff !important; }
.viewport { left: 214px !important; }
.panel { top: 12px !important; left: 8px !important; bottom: auto !important; width: 215px !important;
  box-shadow: none !important; border-radius: 6px !important; }
.panel header, .panel .status, .panel .body > section:not(:has(.layer)),
.panel .body > section:has(.layer) > label, .layer input[type="range"], .layer .muted, .right { display: none !important; }
.panel .body { padding: 7px 10px !important; }
.panel .body > section { padding: 0 !important; border: 0 !important; }
.panel h2, .panel .layer .check { font-size: 20px !important; line-height: 1.16; }
.panel input[type="checkbox"] { accent-color: #1f6feb; }

b.injected_css:
.top, .steps, .log, .nav-buttons { display: none !important; }
.app { grid-template-rows: auto; height: auto; background: #fff; }
.form, .diagnostics { overflow: visible; }
.form { padding: 13px 16px 11px; }
.form h2, .diagnostics h2 { font-size: 26px; line-height: 1.15; margin-bottom: 6px; }
.form h3 { font-size: 22px; margin: 6px 0 3px; }
.viewer-label { font-size: 21px; }
.app { grid-template-columns: minmax(0, 1fr); grid-template-areas: 'centre'; }
.centre { grid-template-rows: auto 240px; }
.diagnostics, .form > div > p.muted, .form > div > .inline { display: none; }
.form .hint, .form table.data, .form .notice { font-size: 20px; line-height: 1.12; }
.form table.data td, .form table.data th { padding: 3px 8px; }
.form table.data:nth-of-type(2) tbody tr:not(:nth-child(3)) { display: none; }
